import java.util.*;
public class Main {
    static class TreeNode { int val; TreeNode left, right; TreeNode(int v){ val = v; } }
    static TreeNode build(String[] a) {
        if (a.length == 0 || a[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(a[0]));
        ArrayDeque<TreeNode> q = new ArrayDeque<>(); q.add(root); int i = 1;
        while (!q.isEmpty() && i < a.length) {
            TreeNode n = q.poll();
            if (i < a.length && !a[i].equals("null")) { n.left = new TreeNode(Integer.parseInt(a[i])); q.add(n.left); } i++;
            if (i < a.length && !a[i].equals("null")) { n.right = new TreeNode(Integer.parseInt(a[i])); q.add(n.right); } i++;
